static const unsigned int kCubinSize = (unsigned int)sizeof(kCubinData);

static int32_t ceildiv_i32(int32_t n, int32_t d) {
    return (n + d - 1) / d;
}

static CUresult ensure_loaded(void) {
    if (g_function != NULL) return CUDA_SUCCESS;
    (void)kCubinSize;
    CUresult r = cuModuleLoadData(&g_module, kCubinData);
    if (r != CUDA_SUCCESS) return r;
    r = cuModuleGetFunction(&g_function, g_module, kFuncSymbol);
    if (r != CUDA_SUCCESS) return r;
    return cuFuncSetAttribute(
        g_function,
        CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES,
        24576
    );
}

CUresult tilelang_batch_decode_paged_hd128_q40_kv8_run_sm120_cuda(
    uint16_t *q,
    const int32_t *q_indptr,
    uint16_t *k_pool,
    uint16_t *v_pool,
    const int32_t *kv_indptr,
    const int32_t *kv_indices,
    const int32_t *kv_last_page_len,
    uint16_t *o,
    int32_t batch_size,
    int32_t total_q_tokens,
    int32_t max_qlen,
    int32_t num_pages,
    int32_t total_pages,
    int32_t num_q_heads,
    int32_t num_kv_heads,
    int32_t page_size,
    float sm_scale,
    CUstream stream
) {
    (void)num_kv_heads;
    (void)page_size;
    (void)sm_scale;
    CUresult r = ensure_loaded();
    if (r != CUDA_SUCCESS) return r;

    int32_t args_batch_size = batch_size;
    int32_t args_batch_size_1 = batch_size;
    int32_t args_batch_size_plus_one = (batch_size + 1);
    int32_t args_num_pages = num_pages;
    int32_t args_num_pages_1 = num_pages;
    int32_t args_total_pages = total_pages;
    int32_t args_total_q_tokens = total_q_tokens;
    int32_t args_total_q_tokens_1 = total_q_tokens;

    void *args[] = {
        &kv_indices,
        &kv_indptr,
        &kv_last_page_len,
        &k_pool,
        &o,
        &q,
        &v_pool,
        &args_batch_size,
        &args_batch_size_1,
        &args_batch_size_plus_one,
        &args_num_pages,
        &args_num_pages_1,
        &args_total_pages,
        &args_total_q_tokens,
        &args_total_q_tokens_1,
    };

    const int block_m = 64;
    int qlen = max_qlen > 0 ? max_qlen : 1;
    int grid_x = (qlen + block_m - 1) / block_m;
    int grid_y = num_q_heads;
    int grid_z = batch_size;

    return cuLaunchKernel(
        g_function,
        grid_x, grid_y, grid_z,
        128, 1, 1,
        24576, stream, args, NULL
    );
}
